def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        cells = [(c, v) for c, v in enumerate(row) if v]
        if len(cells) == 2:
            (c1, v1), (c2, v2) = cells
            if {v1, v2} in ({1, 8}, {4, 7}):
                left, right = sorted((c1, c2))
                out[r][right] = 0
                out[r][left + 1] = grid[r][right]
    return out
